<?php require 'config/db.php';require 'includes/auth.php';require_role(['ADMIN']);$page_title='User Management';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='create'){if(strlen($_POST['password'])<8)exit('Password must be at least 8 characters.');$s=$pdo->prepare('INSERT INTO users(full_name,username,password_hash,role,active) VALUES(?,?,?,?,1)');$s->execute([trim($_POST['full_name']),trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);audit($pdo,'User created',$_POST['username']);$_SESSION['flash']='User created.';}elseif($action==='toggle'){$id=(int)$_POST['id'];if($id===$_SESSION['user']['id'])exit('You cannot disable your own account.');$s=$pdo->prepare('UPDATE users SET active=1-active WHERE id=?');$s->execute([$id]);audit($pdo,'User activation changed','User #'.$id);$_SESSION['flash']='User status updated.';}header('Location:users.php');exit;}$rows=$pdo->query('SELECT id,full_name,username,role,active,created_at FROM users ORDER BY id DESC')->fetchAll();require 'includes/header.php';?><section class="panel"><h2>Create User</h2><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><input name="full_name" placeholder="Full name" required><input name="username" placeholder="Username" required><input type="password" name="password" placeholder="Password (8+ characters)" required><select name="role"><option>VIEWER</option><option>OPERATOR</option><option>ADMIN</option></select><button>Create User</button></form></section><section class="panel"><h2>System Users</h2><table><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['role'])?></td><td><?= $r['active']?'Active':'Disabled' ?></td><td><?php if($r['id']!==$_SESSION['user']['id']):?><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="smallbtn"><?=$r['active']?'Disable':'Enable'?></button></form><?php endif;?></td></tr><?php endforeach;?></table></section><?php require 'includes/footer.php';?>
